CREATE EXTENSION IF NOT EXISTS citext;


CREATE TABLE audit_logs (
    id bigint GENERATED BY DEFAULT AS IDENTITY,
    tenant_id uuid,
    actor_user_id uuid,
    actor_type varchar(30) NOT NULL,
    entity_type varchar(100) NOT NULL,
    entity_id uuid,
    action varchar(100) NOT NULL,
    old_values jsonb,
    new_values jsonb,
    ip varchar(45),
    user_agent text,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_audit_logs PRIMARY KEY (id)
);


CREATE TABLE business_types (
    id uuid NOT NULL,
    business_code varchar(80) NOT NULL,
    business_name varchar(150) NOT NULL,
    description text,
    status varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_business_types PRIMARY KEY (id),
    CONSTRAINT ck_business_types_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED'))
);


CREATE TABLE currencies (
    id uuid NOT NULL,
    currency_code char(3) NOT NULL,
    currency_name varchar(100) NOT NULL,
    currency_symbol varchar(20),
    decimal_places smallint NOT NULL,
    is_active boolean NOT NULL,
    sort_order integer NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_currencies PRIMARY KEY (id),
    CONSTRAINT "AK_currencies_currency_code" UNIQUE (currency_code),
    CONSTRAINT ck_currencies_decimal_places CHECK (decimal_places >= 0),
    CONSTRAINT ck_currencies_sort_order CHECK (sort_order >= 0)
);


CREATE TABLE discount_types (
    id uuid NOT NULL,
    discount_type_code varchar(80) NOT NULL,
    discount_type_name varchar(150) NOT NULL,
    calculation_method varchar(40) NOT NULL,
    is_system_type boolean NOT NULL,
    status varchar(30) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_discount_types PRIMARY KEY (id),
    CONSTRAINT ck_discount_types_calculation_method CHECK (calculation_method IN ('PERCENTAGE', 'FIXED_AMOUNT', 'BUY_X_GET_Y', 'FREE_ITEM', 'PRICE_OVERRIDE')),
    CONSTRAINT ck_discount_types_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED'))
);


CREATE TABLE idempotency_requests (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    actor_user_id uuid NOT NULL,
    endpoint varchar(100) NOT NULL,
    idempotency_key varchar(100) NOT NULL,
    request_hash varchar(64) NOT NULL,
    response_status_code integer NOT NULL,
    response_body text,
    status varchar(20) NOT NULL,
    completed_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    attempt_count integer NOT NULL,
    last_error_code varchar(100),
    processing_leased_until timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_idempotency_requests PRIMARY KEY (id)
);


CREATE TABLE integration_providers (
    id uuid NOT NULL,
    provider_code varchar(80) NOT NULL,
    provider_name varchar(150) NOT NULL,
    provider_category text NOT NULL,
    provider_type text NOT NULL,
    auth_type text NOT NULL,
    api_base_url varchar(500),
    documentation_url varchar(500),
    supports_webhook boolean NOT NULL,
    supports_test_mode boolean NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_integration_providers PRIMARY KEY (id)
);


CREATE TABLE permission_definitions (
    id uuid NOT NULL,
    permission_code varchar(100) NOT NULL,
    module_id uuid NOT NULL,
    feature_id uuid NOT NULL,
    action_type varchar(50) NOT NULL,
    description text,
    is_system boolean NOT NULL,
    is_active boolean NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_permission_definitions PRIMARY KEY (id)
);


CREATE TABLE platform_modules (
    id uuid NOT NULL,
    module_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    description text,
    status varchar(30) NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    module_key varchar(80) NOT NULL,
    module_name varchar(150) NOT NULL,
    is_core_module boolean NOT NULL DEFAULT FALSE,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_modules PRIMARY KEY (id),
    CONSTRAINT ck_platform_modules_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED'))
);


CREATE TABLE platform_sales_channels (
    id uuid NOT NULL,
    channel_code varchar(50) NOT NULL,
    default_name varchar(100) NOT NULL,
    channel_type varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone,
    updated_by uuid,
    CONSTRAINT pk_platform_sales_channels PRIMARY KEY (id),
    CONSTRAINT ck_platform_sales_channels_channel_type CHECK (channel_type IN ('PHYSICAL', 'ONLINE', 'POS', 'AGGREGATOR', 'B2B', 'OTHER'))
);


CREATE TABLE platform_users (
    id uuid NOT NULL,
    email citext NOT NULL,
    normalized_email citext NOT NULL,
    password_hash varchar(255) NOT NULL,
    status varchar(30) NOT NULL,
    first_name varchar(100),
    last_name varchar(100),
    display_name varchar(150),
    phone varchar(40),
    job_title varchar(120),
    email_verified_at timestamp with time zone,
    failed_login_count integer NOT NULL DEFAULT 0,
    locked_until timestamp with time zone,
    last_login_at timestamp with time zone,
    password_changed_at timestamp with time zone,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_users PRIMARY KEY (id),
    CONSTRAINT ck_platform_users_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'LOCKED', 'DELETED')),
    CONSTRAINT fk_platform_users_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL,
    CONSTRAINT fk_platform_users_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE product_option_templates (
    id uuid NOT NULL,
    template_code varchar(80) NOT NULL,
    template_name varchar(150) NOT NULL,
    option_type varchar(40) NOT NULL,
    input_type varchar(40) NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    status varchar(30) NOT NULL,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_product_option_templates PRIMARY KEY (id),
    CONSTRAINT ck_product_option_templates_sort_order CHECK (sort_order >= 0),
    CONSTRAINT ck_product_option_templates_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED'))
);


CREATE TABLE return_policy_templates (
    id uuid NOT NULL,
    template_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    return_window_days integer,
    status varchar(30) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_return_policy_templates PRIMARY KEY (id),
    CONSTRAINT ck_return_policy_templates_return_window_days CHECK (return_window_days IS NULL OR return_window_days >= 0),
    CONSTRAINT ck_return_policy_templates_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED'))
);


CREATE TABLE setting_definitions (
    id uuid NOT NULL,
    setting_key varchar(120) NOT NULL,
    display_name varchar(150) NOT NULL,
    value_type varchar(30) NOT NULL,
    default_value jsonb,
    description text,
    is_tenant_editable boolean NOT NULL,
    status varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_setting_definitions PRIMARY KEY (id)
);


CREATE TABLE tenants (
    id uuid NOT NULL,
    tenant_code varchar(60) NOT NULL,
    tenant_slug varchar(100) NOT NULL,
    display_name varchar(200) NOT NULL,
    status varchar(40) NOT NULL,
    base_currency_code char(3) NOT NULL,
    default_timezone varchar(80) NOT NULL,
    default_locale varchar(20),
    operating_mode varchar(40),
    data_region varchar(50),
    activated_at timestamp with time zone,
    suspended_at timestamp with time zone,
    archived_at timestamp with time zone,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_tenants PRIMARY KEY (id),
    CONSTRAINT ck_tenants_status CHECK (status IN ('draft', 'pending_payment', 'pending_activation', 'active', 'suspended', 'cancelled')),
    CONSTRAINT fk_tenants_base_currency_code_currencies FOREIGN KEY (base_currency_code) REFERENCES currencies (currency_code) ON DELETE RESTRICT
);


CREATE TABLE platform_features (
    id uuid NOT NULL,
    feature_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    description text,
    status varchar(30) NOT NULL,
    platform_module_id uuid NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    feature_key varchar(100) NOT NULL,
    feature_name varchar(150) NOT NULL,
    is_core_feature boolean NOT NULL DEFAULT FALSE,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_features PRIMARY KEY (id),
    CONSTRAINT ck_platform_features_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_platform_features_platform_module_id_platform_modules FOREIGN KEY (platform_module_id) REFERENCES platform_modules (id) ON DELETE RESTRICT
);


CREATE TABLE platform_auth_sessions (
    id uuid NOT NULL,
    platform_user_id uuid NOT NULL,
    status varchar(30) NOT NULL,
    session_token_hash varchar(255) NOT NULL,
    ip_address varchar(45),
    user_agent text,
    device_name varchar(150),
    last_seen_at timestamp with time zone,
    revoked_at timestamp with time zone,
    revoked_by_platform_user_id uuid,
    revoke_reason varchar(250),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_auth_sessions PRIMARY KEY (id),
    CONSTRAINT ck_platform_auth_sessions_status CHECK (status IN ('ACTIVE', 'EXPIRED', 'REVOKED')),
    CONSTRAINT fk_platform_auth_sessions_platform_user_id_platform_users FOREIGN KEY (platform_user_id) REFERENCES platform_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_platform_auth_sessions_revoked_by_platform_user_id_platform_users FOREIGN KEY (revoked_by_platform_user_id) REFERENCES platform_users (id) ON DELETE RESTRICT
);


CREATE TABLE platform_integrations (
    id uuid NOT NULL,
    integration_provider_id uuid NOT NULL,
    integration_code varchar(80) NOT NULL,
    integration_name varchar(150) NOT NULL,
    integration_category text NOT NULL,
    integration_status text NOT NULL,
    environment text NOT NULL,
    currency_code char(3),
    is_enabled boolean NOT NULL,
    is_default boolean NOT NULL,
    base_url varchar(500),
    inbound_webhook_url varchar(500),
    connected_at timestamp with time zone,
    disconnected_at timestamp with time zone,
    last_successful_request_at timestamp with time zone,
    last_failed_request_at timestamp with time zone,
    last_failure_reason text,
    created_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_integrations PRIMARY KEY (id),
    CONSTRAINT fk_platform_integrations_132de113 FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_platform_integrations_3bea47ad FOREIGN KEY (integration_provider_id) REFERENCES integration_providers (id) ON DELETE RESTRICT,
    CONSTRAINT fk_platform_integrations_ea0ba30a FOREIGN KEY (currency_code) REFERENCES currencies (currency_code) ON DELETE RESTRICT
);


CREATE TABLE platform_password_reset_tokens (
    id uuid NOT NULL,
    platform_user_id uuid,
    status varchar(30) NOT NULL,
    token_hash varchar(255) NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_password_reset_tokens PRIMARY KEY (id),
    CONSTRAINT ck_platform_password_reset_tokens_expires_after_requested CHECK (expires_at > requested_at),
    CONSTRAINT ck_platform_password_reset_tokens_status CHECK (status IN ('PENDING', 'USED', 'EXPIRED', 'REVOKED')),
    CONSTRAINT fk_platform_password_reset_tokens_platform_user_id_platform_users FOREIGN KEY (platform_user_id) REFERENCES platform_users (id) ON DELETE RESTRICT
);


CREATE TABLE platform_permissions (
    id uuid NOT NULL,
    permission_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    module_key varchar(100) NOT NULL,
    description text,
    status varchar(30) NOT NULL,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_permissions PRIMARY KEY (id),
    CONSTRAINT ck_platform_permissions_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_platform_permissions_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL,
    CONSTRAINT fk_platform_permissions_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE platform_roles (
    id uuid NOT NULL,
    role_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    description text,
    is_system_role boolean NOT NULL DEFAULT FALSE,
    status varchar(30) NOT NULL,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_roles PRIMARY KEY (id),
    CONSTRAINT ck_platform_roles_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_platform_roles_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL,
    CONSTRAINT fk_platform_roles_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE platform_settings (
    id uuid NOT NULL,
    setting_key varchar(120) NOT NULL,
    setting_value jsonb NOT NULL,
    is_secret boolean NOT NULL DEFAULT FALSE,
    description text,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_platform_settings PRIMARY KEY (id),
    CONSTRAINT fk_platform_settings_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE subscription_addons (
    id uuid NOT NULL,
    addon_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    description text,
    status varchar(30) NOT NULL,
    price_amount numeric(18,2) NOT NULL,
    addon_name varchar(150) NOT NULL,
    addon_type varchar(40) NOT NULL,
    billing_cycle varchar(40) NOT NULL,
    base_currency_code char(3) NOT NULL,
    base_price numeric(18,4) NOT NULL,
    quantity_based boolean NOT NULL DEFAULT FALSE,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscription_addons PRIMARY KEY (id),
    CONSTRAINT ck_subscription_addons_base_price CHECK (base_price >= 0),
    CONSTRAINT ck_subscription_addons_price_amount CHECK (price_amount >= 0),
    CONSTRAINT ck_subscription_addons_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_subscription_addons_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL,
    CONSTRAINT fk_subscription_addons_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE subscription_plans (
    id uuid NOT NULL,
    plan_code varchar(80) NOT NULL,
    name varchar(200) NOT NULL,
    description text,
    status varchar(30) NOT NULL,
    billing_interval varchar(255) NOT NULL,
    base_currency char(3) NOT NULL,
    price_amount numeric(18,2) NOT NULL,
    max_outlets integer,
    max_users integer,
    max_tills integer,
    plan_name varchar(150) NOT NULL,
    billing_cycle varchar(40) NOT NULL,
    base_currency_code char(3) NOT NULL,
    base_price numeric(18,4) NOT NULL,
    trial_days integer NOT NULL DEFAULT 0,
    is_public boolean NOT NULL DEFAULT TRUE,
    is_custom_plan boolean NOT NULL DEFAULT FALSE,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscription_plans PRIMARY KEY (id),
    CONSTRAINT ck_subscription_plans_base_price CHECK (base_price >= 0),
    CONSTRAINT ck_subscription_plans_billing_interval CHECK (billing_interval IN ('MONTHLY', 'YEARLY', 'ONE_TIME')),
    CONSTRAINT ck_subscription_plans_price_amount CHECK (price_amount >= 0),
    CONSTRAINT ck_subscription_plans_trial_days CHECK (trial_days >= 0),
    CONSTRAINT fk_subscription_plans_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL,
    CONSTRAINT fk_subscription_plans_updated_by_platform_user_id_platform_users FOREIGN KEY (updated_by_platform_user_id) REFERENCES platform_users (id) ON DELETE SET NULL
);


CREATE TABLE business_type_option_templates (
    id uuid NOT NULL,
    business_type_id uuid NOT NULL,
    option_template_id uuid NOT NULL,
    is_default_template boolean NOT NULL DEFAULT FALSE,
    sort_order integer NOT NULL DEFAULT 0,
    status varchar(30) NOT NULL,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_business_type_option_templates PRIMARY KEY (id),
    CONSTRAINT ck_business_type_option_templates_sort_order CHECK (sort_order >= 0),
    CONSTRAINT ck_business_type_option_templates_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_business_type_option_templates_business_type_id_business_types FOREIGN KEY (business_type_id) REFERENCES business_types (id) ON DELETE RESTRICT,
    CONSTRAINT fk_business_type_option_templates_option_template_id_product_option_templates FOREIGN KEY (option_template_id) REFERENCES product_option_templates (id) ON DELETE RESTRICT
);


CREATE TABLE product_option_template_values (
    id uuid NOT NULL,
    option_template_id uuid NOT NULL,
    value_code varchar(80) NOT NULL,
    value_name varchar(150) NOT NULL,
    display_name varchar(150),
    color_hex varchar(20),
    image_url varchar(500),
    sort_order integer NOT NULL DEFAULT 0,
    status varchar(30) NOT NULL,
    created_by_platform_user_id uuid,
    updated_by_platform_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_product_option_template_values PRIMARY KEY (id),
    CONSTRAINT ck_product_option_template_values_sort_order CHECK (sort_order >= 0),
    CONSTRAINT ck_product_option_template_values_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_product_option_template_values_option_template_id_product_option_templates FOREIGN KEY (option_template_id) REFERENCES product_option_templates (id) ON DELETE RESTRICT
);


CREATE TABLE cash_movement_types (
    id uuid NOT NULL,
    tenant_id uuid,
    movement_type_code varchar(60) NOT NULL,
    movement_type_name varchar(150) NOT NULL,
    direction varchar(40) NOT NULL,
    affects_expected_cash boolean NOT NULL,
    requires_reason boolean NOT NULL,
    is_system_type boolean NOT NULL,
    status varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_cash_movement_types PRIMARY KEY (id),
    CONSTRAINT ck_cash_movement_types_direction CHECK (direction <> ''),
    CONSTRAINT ck_cash_movement_types_status CHECK (status <> ''),
    CONSTRAINT fk_cash_movement_types_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


CREATE TABLE choice_groups (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    group_code varchar(80) NOT NULL,
    group_name varchar(150) NOT NULL,
    min_select integer NOT NULL DEFAULT 0,
    max_select integer NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    status varchar(40) NOT NULL,
    created_by_tenant_user_id uuid,
    updated_by_tenant_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_choice_groups PRIMARY KEY (id),
    CONSTRAINT "AK_choice_groups_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_choice_groups_max_select CHECK (max_select > 0),
    CONSTRAINT ck_choice_groups_max_select_min_select CHECK (max_select >= min_select),
    CONSTRAINT ck_choice_groups_min_select CHECK (min_select >= 0),
    CONSTRAINT ck_choice_groups_sort_order CHECK (sort_order >= 0),
    CONSTRAINT ck_choice_groups_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_choice_groups_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


CREATE TABLE integration_outbox_messages (
    id uuid NOT NULL,
    message_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    aggregate_sequence bigint NOT NULL,
    tenant_id uuid,
    correlation_id uuid NOT NULL,
    causation_id uuid,
    payload_json jsonb NOT NULL,
    payload_schema_version integer NOT NULL,
    deduplication_key varchar(180) NOT NULL,
    status varchar(24) NOT NULL,
    attempt_count integer NOT NULL,
    available_at timestamp with time zone NOT NULL,
    lease_owner varchar(120),
    lease_expires_at timestamp with time zone,
    processed_at timestamp with time zone,
    last_error_code varchar(100),
    sanitized_last_error varchar(500),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_integration_outbox_messages PRIMARY KEY (id),
    CONSTRAINT ck_integration_outbox_attempts CHECK (attempt_count >= 0),
    CONSTRAINT ck_integration_outbox_schema CHECK (payload_schema_version > 0),
    CONSTRAINT ck_integration_outbox_sequence CHECK (aggregate_sequence > 0),
    CONSTRAINT ck_integration_outbox_status CHECK (status IN ('PENDING','PROCESSING','DELIVERED','FAILED_RETRYABLE','FAILED_FINAL')),
    CONSTRAINT fk_integration_outbox_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


CREATE TABLE media_assets (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    container_name varchar(100) NOT NULL,
    storage_key varchar(500) NOT NULL,
    public_url varchar(1000),
    original_file_name varchar(255) NOT NULL,
    mime_type varchar(100) NOT NULL,
    file_extension varchar(20) NOT NULL,
    file_size_bytes bigint NOT NULL,
    width_px integer,
    height_px integer,
    checksum_hash varchar(128) NOT NULL,
    asset_type varchar(40) NOT NULL,
    asset_purpose varchar(80) NOT NULL,
    status varchar(40) NOT NULL,
    deletion_retry_count integer NOT NULL DEFAULT 0,
    next_retry_at timestamp with time zone,
    last_deletion_error text,
    created_by_tenant_user_id uuid,
    updated_by_tenant_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_media_assets PRIMARY KEY (id),
    CONSTRAINT ak_media_assets_tenant_id_id UNIQUE (tenant_id, id),
    CONSTRAINT ck_media_assets_asset_type CHECK (asset_type IN ('IMAGE')),
    CONSTRAINT ck_media_assets_file_size_bytes CHECK (file_size_bytes > 0),
    CONSTRAINT ck_media_assets_height_px CHECK (height_px IS NULL OR height_px > 0),
    CONSTRAINT ck_media_assets_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETE_PENDING', 'DELETED')),
