    CONSTRAINT ck_onboarding_operations_provisioning_status CHECK (provisioning_status IN ('PROCESSING','SUCCEEDED','FAILED_RETRYABLE','FAILED_FINAL')),
    CONSTRAINT ck_onboarding_operations_status CHECK (status IN ('PROCESSING','SUCCEEDED','FAILED_RETRYABLE','FAILED_FINAL')),
