    description text,
    discount_scope varchar(40) NOT NULL,
    discount_value numeric(18,4) NOT NULL,
    currency_code char(3),
    max_discount_amount numeric(18,4),
    min_order_amount numeric(18,4),
    min_quantity numeric(18,4),
    requires_manager_approval boolean NOT NULL DEFAULT FALSE,
    is_stackable boolean NOT NULL DEFAULT FALSE,
    stacking_group_code varchar(80),
    priority integer NOT NULL DEFAULT 0,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    status varchar(30) NOT NULL,
    created_by_tenant_user_id uuid,
    updated_by_tenant_user_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_discount_policies PRIMARY KEY (id),
    CONSTRAINT "AK_discount_policies_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_discount_policies_amounts CHECK ((max_discount_amount IS NULL OR max_discount_amount >= 0) AND (min_order_amount IS NULL OR min_order_amount >= 0) AND (min_quantity IS NULL OR min_quantity > 0)),
    CONSTRAINT ck_discount_policies_discount_scope CHECK (discount_scope IN ('ORDER', 'LINE', 'PRODUCT', 'CATEGORY', 'BRAND', 'COLLECTION', 'BATCH')),
    CONSTRAINT ck_discount_policies_discount_value CHECK (discount_value >= 0),
    CONSTRAINT ck_discount_policies_period CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at >= starts_at),
    CONSTRAINT ck_discount_policies_priority CHECK (priority >= 0),
    CONSTRAINT ck_discount_policies_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_discount_policies_created_by_tenant_user_id_tenant_users FOREIGN KEY (created_by_tenant_user_id) REFERENCES tenant_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_discount_policies_currency_code_currencies FOREIGN KEY (currency_code) REFERENCES currencies (currency_code) ON DELETE RESTRICT,
