    CONSTRAINT ck_subscription_invoices_balance_due CHECK (balance_due IS NULL OR balance_due >= 0),
    CONSTRAINT ck_subscription_invoices_discount_amount CHECK (discount_amount IS NULL OR discount_amount >= 0),
    CONSTRAINT ck_subscription_invoices_paid_amount CHECK (paid_amount IS NULL OR paid_amount >= 0),
    CONSTRAINT ck_subscription_invoices_subtotal_amount CHECK (subtotal_amount IS NULL OR subtotal_amount >= 0),
    CONSTRAINT ck_subscription_invoices_tax_amount CHECK (tax_amount IS NULL OR tax_amount >= 0),
    CONSTRAINT ck_subscription_invoices_total_amount CHECK (total_amount >= 0),
