    withdrawn_at timestamp with time zone,
    ip_address inet,
    user_agent text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_customer_consents PRIMARY KEY (id),
    CONSTRAINT ck_customer_consents_consent_source CHECK (consent_source IN ('POS', 'ECOMMERCE', 'CLICK_AND_COLLECT', 'ADMIN', 'IMPORT')),
    CONSTRAINT ck_customer_consents_consent_status CHECK (consent_status IN ('GRANTED', 'WITHDRAWN', 'EXPIRED')),
    CONSTRAINT ck_customer_consents_consent_type CHECK (consent_type IN ('MARKETING_EMAIL', 'MARKETING_SMS', 'MARKETING_WHATSAPP', 'TERMS', 'PRIVACY')),
    CONSTRAINT fk_customer_consents_customer_id_customers FOREIGN KEY (tenant_id, customer_id) REFERENCES customers (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_customer_consents_sales_channel_id_sales_channels FOREIGN KEY (tenant_id, sales_channel_id) REFERENCES sales_channels (tenant_id, id) ON DELETE RESTRICT,
