);


CREATE TABLE customer_verification_otps (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    customer_id uuid,
    status varchar(40) NOT NULL,
    attempt_count integer NOT NULL DEFAULT 0,
    max_attempts integer NOT NULL DEFAULT 5,
    normalized_recipient_value varchar(150) NOT NULL,
    verification_purpose varchar(40) NOT NULL,
    delivery_channel varchar(40) NOT NULL,
    recipient_value varchar(150) NOT NULL,
    otp_hash varchar(255),
    resend_count integer NOT NULL DEFAULT 0,
    sent_at timestamp with time zone NOT NULL,
    last_sent_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    verified_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    provider_name varchar(80),
    provider_message_id varchar(150),
    request_ip_address inet,
    request_user_agent text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_customer_verification_otps PRIMARY KEY (id),
    CONSTRAINT "AK_customer_verification_otps_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_customer_verification_otps_attempt_count CHECK (attempt_count >= 0),
    CONSTRAINT ck_customer_verification_otps_delivery_channel CHECK (delivery_channel IN ('EMAIL', 'SMS', 'WHATSAPP')),
    CONSTRAINT ck_customer_verification_otps_expires_at CHECK (expires_at > sent_at),
    CONSTRAINT ck_customer_verification_otps_max_attempts CHECK (max_attempts > 0),
    CONSTRAINT ck_customer_verification_otps_resend_count CHECK (resend_count >= 0),
    CONSTRAINT ck_customer_verification_otps_status CHECK (status IN ('PENDING', 'VERIFIED', 'EXPIRED', 'INVALIDATED', 'FAILED')),
    CONSTRAINT ck_customer_verification_otps_verification_purpose CHECK (verification_purpose IN ('EMAIL_VERIFY', 'PHONE_VERIFY', 'PASSWORD_RESET', 'LOGIN_VERIFY')),
    CONSTRAINT fk_customer_verification_otps_customer_id_customers FOREIGN KEY (tenant_id, customer_id) REFERENCES customers (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_customer_verification_otps_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


