    CONSTRAINT ck_outlet_business_hours_validity CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until >= valid_from),
    CONSTRAINT fk_outlet_business_hours_outlet_id_outlets FOREIGN KEY (outlet_id) REFERENCES outlets (id) ON DELETE RESTRICT,
    CONSTRAINT fk_outlet_business_hours_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


