    CONSTRAINT ck_product_attribute_values_nonnull_values CHECK ((CASE WHEN attribute_value_text IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN attribute_value_number IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN attribute_value_boolean IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN attribute_value_date IS NOT NULL THEN 1 ELSE 0 END) <= 1),
    CONSTRAINT ck_product_attribute_values_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
