CREATE TABLE receipt_template_assignments (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    receipt_template_version_id uuid NOT NULL,
    assignment_scope varchar(40) NOT NULL,
    outlet_id uuid,
    till_id uuid,
    pos_device_id uuid,
    is_default boolean NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    created_by_tenant_user_id uuid,
    updated_at timestamp with time zone NOT NULL,
    updated_by_tenant_user_id uuid,
    CONSTRAINT pk_receipt_template_assignments PRIMARY KEY (id),
    CONSTRAINT ck_receipt_template_assignments_assignment_scope CHECK (assignment_scope IN ('OUTLET', 'TILL', 'POS_DEVICE')),
    CONSTRAINT ck_receipt_template_assignments_effective_dates CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT ck_receipt_template_assignments_scope_rules CHECK ((assignment_scope = 'OUTLET' AND outlet_id IS NOT NULL AND till_id IS NULL AND pos_device_id IS NULL) OR (assignment_scope = 'TILL' AND outlet_id IS NULL AND till_id IS NOT NULL AND pos_device_id IS NULL) OR (assignment_scope = 'POS_DEVICE' AND outlet_id IS NULL AND till_id IS NULL AND pos_device_id IS NOT NULL)),
    CONSTRAINT ck_receipt_template_assignments_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DELETED')),
    CONSTRAINT fk_receipt_template_assignments_created_by_tenant_users FOREIGN KEY (created_by_tenant_user_id) REFERENCES tenant_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_outlet_id_outlets FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_pos_device_id_pos_devices FOREIGN KEY (tenant_id, pos_device_id) REFERENCES pos_devices (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_receipt_template_version_id_receipt_template_versions FOREIGN KEY (tenant_id, receipt_template_version_id) REFERENCES receipt_template_versions (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_till_id_tills FOREIGN KEY (tenant_id, till_id) REFERENCES tills (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_receipt_template_assignments_updated_by_tenant_users FOREIGN KEY (updated_by_tenant_user_id) REFERENCES tenant_users (id) ON DELETE RESTRICT
);


