CREATE TABLE inventory_balances (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    inventory_location_id uuid NOT NULL,
    product_id uuid NOT NULL,
    product_variant_id uuid,
    product_batch_id uuid,
    on_hand_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    reserved_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    damaged_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    quarantine_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    available_quantity numeric(18,4) GENERATED ALWAYS AS (on_hand_quantity - reserved_quantity - damaged_quantity - quarantine_quantity) STORED NOT NULL,
    row_version bigint NOT NULL DEFAULT 0,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_inventory_balances PRIMARY KEY (id),
    CONSTRAINT "AK_inventory_balances_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_inventory_balances_damaged_quantity CHECK (damaged_quantity >= 0),
    CONSTRAINT ck_inventory_balances_on_hand_quantity CHECK (on_hand_quantity >= 0),
    CONSTRAINT ck_inventory_balances_quarantine_quantity CHECK (quarantine_quantity >= 0),
    CONSTRAINT ck_inventory_balances_reserved_quantity CHECK (reserved_quantity >= 0),
    CONSTRAINT ck_inventory_balances_row_version CHECK (row_version >= 0),
    CONSTRAINT fk_inventory_balances_inventory_location_id_inventory_locations FOREIGN KEY (tenant_id, inventory_location_id) REFERENCES inventory_locations (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_inventory_balances_product_batch_id_product_batches FOREIGN KEY (tenant_id, product_batch_id) REFERENCES product_batches (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_inventory_balances_product_id_products FOREIGN KEY (tenant_id, product_id) REFERENCES products (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_inventory_balances_product_variant_id_product_variants FOREIGN KEY (tenant_id, product_variant_id) REFERENCES product_variants (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_inventory_balances_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


