CREATE TABLE return_inspection_drafts (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    outlet_id uuid NOT NULL,
    sale_id uuid NOT NULL,
    status varchar(20) NOT NULL,
    version integer NOT NULL DEFAULT 1,
    expires_at timestamp with time zone NOT NULL,
    validated_at timestamp with time zone,
    validated_by_tenant_user_id uuid,
    requires_inspection boolean NOT NULL DEFAULT FALSE,
    requires_manager_approval boolean NOT NULL DEFAULT FALSE,
    resolution_type varchar(20),
    resolution_selected_at timestamp with time zone,
    resolution_selected_by_tenant_user_id uuid,
    refund_method_code varchar(40),
    refund_method_selected_at timestamp with time zone,
    refund_method_selected_by_tenant_user_id uuid,
