    CONSTRAINT "AK_return_inspection_drafts_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_return_inspection_drafts_expires_at CHECK (expires_at > created_at),
    CONSTRAINT ck_return_inspection_drafts_resolution_fields CHECK ((resolution_type IS NULL AND resolution_selected_at IS NULL AND resolution_selected_by_tenant_user_id IS NULL) OR (resolution_type IS NOT NULL AND resolution_selected_at IS NOT NULL AND resolution_selected_by_tenant_user_id IS NOT NULL)),
    CONSTRAINT ck_return_inspection_drafts_resolution_type CHECK (resolution_type IS NULL OR resolution_type IN ('REFUND', 'EXCHANGE')),
    CONSTRAINT ck_return_inspection_drafts_status CHECK (status IN ('DRAFT', 'VALIDATED', 'CONSUMED', 'CANCELLED')),
    CONSTRAINT ck_return_inspection_drafts_version CHECK (version >= 1),
    CONSTRAINT "FK_return_inspection_drafts_tenants_tenant_id" FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT,
    CONSTRAINT fk_return_inspection_drafts_outlet_tenant FOREIGN KEY (tenant_id, outlet_id) REFERENCES outlets (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_return_inspection_drafts_resolution_user_tenant FOREIGN KEY (tenant_id, resolution_selected_by_tenant_user_id) REFERENCES tenant_users (tenant_id, id) ON DELETE RESTRICT,
    CONSTRAINT fk_return_inspection_drafts_sale_tenant FOREIGN KEY (tenant_id, sale_id) REFERENCES sales_orders (tenant_id, id) ON DELETE RESTRICT
);


CREATE TABLE sales_order_lines (
