    tenant_id uuid NOT NULL,
    product_id uuid NOT NULL,
    product_variant_id uuid,
    uom_id uuid NOT NULL,
    price_list_item_id uuid,
    sku_snapshot varchar(100),
    barcode_snapshot varchar(120),
    product_name_snapshot varchar(200) NOT NULL,
    variant_name_snapshot varchar(200),
    department_name_snapshot varchar(150),
    category_name_snapshot varchar(150),
    subcategory_name_snapshot varchar(150),
    brand_name_snapshot varchar(150),
    line_note varchar(500),
    uom_code_snapshot varchar(50) NOT NULL,
    uom_name_snapshot varchar(100) NOT NULL,
    product_type_snapshot varchar(40) NOT NULL,
    product_structure_snapshot varchar(40) NOT NULL,
    fulfilled_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    cancelled_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    returned_quantity numeric(18,4) NOT NULL DEFAULT 0.0,
    original_unit_price numeric(18,4) NOT NULL,
    unit_price numeric(18,4) NOT NULL,
    line_subtotal_amount numeric(18,4) NOT NULL,
    line_discount_amount numeric(18,4) NOT NULL DEFAULT 0.0,
    line_tax_amount numeric(18,4) NOT NULL DEFAULT 0.0,
    line_status varchar(40) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_sales_order_lines PRIMARY KEY (id),
    CONSTRAINT "AK_sales_order_lines_tenant_id_id" UNIQUE (tenant_id, id),
    CONSTRAINT ck_sales_order_lines_cancelled_quantity CHECK (cancelled_quantity >= 0),
    CONSTRAINT ck_sales_order_lines_fulfilled_quantity CHECK (fulfilled_quantity >= 0),
    CONSTRAINT ck_sales_order_lines_line_discount_amount CHECK (line_discount_amount >= 0),
    CONSTRAINT ck_sales_order_lines_line_status CHECK (line_status IN ('ACTIVE', 'PARTIALLY_FULFILLED', 'FULFILLED', 'CANCELLED', 'RETURNED')),
    CONSTRAINT ck_sales_order_lines_line_subtotal_amount CHECK (line_subtotal_amount >= 0),
    CONSTRAINT ck_sales_order_lines_line_tax_amount CHECK (line_tax_amount >= 0),
    CONSTRAINT ck_sales_order_lines_line_total_amount CHECK (line_total_amount >= 0),
    CONSTRAINT ck_sales_order_lines_original_unit_price CHECK (original_unit_price >= 0),
    CONSTRAINT ck_sales_order_lines_quantity CHECK (quantity > 0),
