    sha256 character varying(64) NOT NULL,
    evidence_type character varying(40) NOT NULL,
    uploaded_by_type character varying(40) NOT NULL,
    uploaded_by_id uuid,
    submission_version bigint NOT NULL,
    is_active boolean NOT NULL,
    superseded_at timestamp with time zone,
    scan_status character varying(40) NOT NULL,
    scan_failure_code character varying(100),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone,
    CONSTRAINT pk_subscription_payment_evidence PRIMARY KEY (id),
    CONSTRAINT ck_subscription_payment_evidence_file_size CHECK (file_size > 0),
    CONSTRAINT fk_subscription_payment_evidence_invoice FOREIGN KEY (invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_evidence_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


CREATE TABLE subscription_payment_links (
    id uuid NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    payment_link_token_hash varchar(255),
    subscription_invoice_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    token_hash varchar(255),
    provider_name varchar(120),
    provider_payment_link_id varchar(150),
    payment_url varchar(700),
    link_status varchar(40) NOT NULL,
    sent_to_email varchar(255),
    sent_at timestamp with time zone,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    last_reminder_at timestamp with time zone,
    reminder_count integer NOT NULL DEFAULT 0,
    created_by_platform_user_id uuid,
    payment_transaction_id uuid,
    purpose character varying(60) NOT NULL,
    allowed_actions character varying(255) NOT NULL,
    recipient_type character varying(60) NOT NULL,
    recipient_identifier_hash character varying(64),
    token_provisioned_at timestamp with time zone,
    last_accessed_at timestamp with time zone,
    version bigint NOT NULL DEFAULT 1,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscription_payment_links PRIMARY KEY (id),
    CONSTRAINT ck_subscription_payment_links_expires_at_created_at CHECK (expires_at IS NULL OR expires_at > created_at),
    CONSTRAINT ck_subscription_payment_links_reminder_count CHECK (reminder_count IS NULL OR reminder_count >= 0),
    CONSTRAINT fk_subscription_payment_links_created_by_platform_user_id_platform_users FOREIGN KEY (created_by_platform_user_id) REFERENCES platform_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_links_invoice_id_subscription_invoices FOREIGN KEY (invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_links_subscription_invoice_id_subscription_invoices FOREIGN KEY (subscription_invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_links_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


CREATE TABLE subscription_payment_transactions (
    id uuid NOT NULL,
    amount numeric(18,2) NOT NULL,
    provider_transaction_reference varchar(255) NOT NULL,
    subscription_invoice_id uuid NOT NULL,
    subscription_payment_link_id uuid,
    tenant_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    payment_link_id uuid,
    transaction_type varchar(40) NOT NULL,
    provider_name varchar(120) NOT NULL,
    provider_transaction_id varchar(150),
    idempotency_key varchar(150),
    transaction_status varchar(40) NOT NULL,
    currency_code char(3) NOT NULL,
    provider_fee numeric(18,4) NOT NULL,
    net_amount numeric(18,4) NOT NULL,
    paid_at timestamp with time zone,
    failed_at timestamp with time zone,
    failure_reason text,
    provider_response_json jsonb,
    tenant_subscription_id uuid NOT NULL,
    expected_amount numeric(18,2) NOT NULL,
    submitted_amount numeric(18,2),
    approved_amount numeric(18,2),
    payment_method character varying(40),
    manual_reference character varying(255),
    manual_reference_normalized character varying(255),
    payment_date timestamp with time zone,
    submitted_at timestamp with time zone,
    submitted_by_type character varying(40),
    submitted_by_id uuid,
    payer_note text,
    verified_at timestamp with time zone,
    verified_by_platform_user_id uuid,
    review_note text,
    rejection_reason_code character varying(100),
    failure_code character varying(100),
    last_command_idempotency_key_hash character varying(64),
    last_command_request_hash character varying(64),
    submission_version bigint NOT NULL DEFAULT 0,
    version bigint NOT NULL DEFAULT 1,
    provider_event_id character varying(180),
    provider_checkout_url character varying(700),
    provider_customer_reference_id character varying(180),
    provider_status character varying(80),
    provider_callback_receipt_json jsonb,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_subscription_payment_transactions PRIMARY KEY (id),
    CONSTRAINT ck_subscription_payment_transactions_amount CHECK (amount >= 0),
    CONSTRAINT ck_subscription_payment_transactions_expected_amount CHECK (expected_amount >= 0),
    CONSTRAINT ck_subscription_payment_transactions_net_amount CHECK (net_amount IS NULL OR net_amount >= 0),
    CONSTRAINT ck_subscription_payment_transactions_provider_fee CHECK (provider_fee IS NULL OR provider_fee >= 0),
    CONSTRAINT ck_subscription_payment_transactions_submitted_amount CHECK (submitted_amount IS NULL OR submitted_amount > 0),
    CONSTRAINT fk_subscription_payment_transactions_invoice_id_subscription_invoices FOREIGN KEY (invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_transactions_payment_link_id_subscription_payment_links FOREIGN KEY (payment_link_id) REFERENCES subscription_payment_links (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_transactions_subscription_invoice_id_subscription_invoices FOREIGN KEY (subscription_invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_transactions_subscription_payment_link_id_subscription_payment_links FOREIGN KEY (subscription_payment_link_id) REFERENCES subscription_payment_links (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_transactions_tenant_id_tenants FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_transactions_tenant_subscription_id FOREIGN KEY (tenant_subscription_id) REFERENCES tenant_subscriptions (id) ON DELETE RESTRICT
);


CREATE TABLE subscription_payment_reviews (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    action character varying(40) NOT NULL,
    status_before character varying(40) NOT NULL,
    status_after character varying(40) NOT NULL,
    actor_type character varying(40) NOT NULL,
    actor_id uuid,
    review_note text,
    reason_code character varying(100),
    idempotency_key_hash character varying(64) NOT NULL,
    request_hash character varying(64) NOT NULL,
    correlation_id uuid NOT NULL,
    payment_version bigint NOT NULL,
    submitted_amount_snapshot numeric(18,2),
    expected_amount_snapshot numeric(18,2) NOT NULL,
    currency_snapshot character varying(3) NOT NULL,
    evidence_id_snapshot uuid,
    evidence_version_snapshot bigint,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone,
    CONSTRAINT pk_subscription_payment_reviews PRIMARY KEY (id),
    CONSTRAINT fk_subscription_payment_reviews_actor FOREIGN KEY (actor_id) REFERENCES platform_users (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_reviews_invoice FOREIGN KEY (invoice_id) REFERENCES subscription_invoices (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_reviews_payment FOREIGN KEY (payment_id) REFERENCES subscription_payment_transactions (id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_payment_reviews_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id) ON DELETE RESTRICT
);


